css:
.bk-isu1 h2{font-size: 1.55em; border-left: 8px solid #2b5d8a; padding: 2px 0 2px 10px; margin: 0 0 5mm;}
.bk-isu1 h3{font-size: 1.18em; color: #2b5d8a; margin: 6mm 0 2mm; border-bottom: 1px solid #c9d6e3;}
.bk-isu1 p{margin: 0 0 3mm;}
.bk-isu1 .point{background: #eef4fa; border: 1px solid #c9d6e3; border-radius: 4px; padding: 3mm 5mm; margin: 3mm 0 4mm;}
.bk-isu1 .warn{background: #fff6e8; border: 1px solid #f0d3a0; border-radius: 4px; padding: 3mm 5mm; margin: 3mm 0 4mm;}
.bk-isu1 .tip{background: #f1f7ee; border: 1px solid #c7dcb9; border-radius: 4px; padding: 3mm 5mm; margin: 3mm 0 4mm;}
.bk-isu1 table{border-collapse: collapse; width: 100%; font-size: 0.909em; margin: 2mm 0 4mm;}
.bk-isu1 th,.bk-isu1 td{border: 1px solid #aab; padding: 1.5mm 2mm; vertical-align: top;}
.bk-isu1 th{background: #e3ebf3;}
.bk-isu1 .chair{border: 1px solid #ccd; border-radius: 6px; padding: 3mm 4mm; margin: 0 0 5mm; display: flex; flex-wrap: wrap; gap: 4mm;}
.bk-isu1 .chair .fig{flex: 0 0 200px; text-align: center;}
.bk-isu1 .chair .txt{flex: 1 1 260px; min-width: 0;}
.bk-isu1 .chair h4{margin: 0; font-size: 1.27em; line-height: 1.4;}
.bk-isu1 .chair .mk{color: #555; font-size: 0.909em; margin-bottom: 1mm;}
.bk-isu1 .chair .no{display: inline-block; background: #2b5d8a; color: #fff; border-radius: 4px; padding: 0 2.5mm; font-size: 1.09em;}
.bk-isu1 .cap{font-size: 0.773em; color: #777;}
.bk-isu1 .pr th{width: 30%; text-align: left;}
.bk-isu1 .pr td{font-weight: bold; color: #a33;}
.bk-isu1 .good::before{content: "◎ "; color: #2a7a2a; font-weight: bold;}
.bk-isu1 .bad::before{content: "△ "; color: #b36b00; font-weight: bold;}
.bk-isu1 .sit{background: #f6f6ee; padding: 1.5mm 3mm; border-radius: 4px;}
.bk-isu1 ul,.bk-isu1 ol{margin: 0 0 3mm; padding-left: 6mm;}
.bk-isu1 li{margin-bottom: 1mm;}
.bk-isu1 .check li{list-style: none; margin-left: -6mm;}
.bk-isu1 .check li::before{content: "□ "; font-size: 1.18em;}
.bk-isu1 .small{font-size: 0.864em; color: #555;}
.bk-isu1 .big{font-size: 1.27em; font-weight: bold;}
.bk-isu1 .center{text-align: center;}
